import 'package:flutter/material.dart';
import '../services/agent_service.dart';
import '../domain/kernel/agent_observability.dart';
import '../theme/pro_theme.dart';
import '../widgets/pro_app_bar.dart';
class ProDashboard extends StatefulWidget { const ProDashboard({super.key}); @override State<ProDashboard> createState()=>_ProDashboardState(); }
class _ProDashboardState extends State<ProDashboard>{
 final _agent=AgentService.instance; Future<AgentObservabilitySummary>? _future;
 @override void initState(){super.initState();_load();}
 void _load(){_future=_agent.observabilitySummaryForConversation('global');}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:ProTheme.bgDark,appBar:const ProAppBar(title:'Operational Control Center',breadcrumb:'AgentOS / Dashboard'),body:Container(decoration:const BoxDecoration(gradient:ProTheme.bgGradient),child:RefreshIndicator(onRefresh:()async{setState(_load);await _future;},child:FutureBuilder<AgentObservabilitySummary>(future:_future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text(s.error.toString(),style:const TextStyle(color:ProTheme.dangerRed)));final m=s.data!;return ListView(padding:const EdgeInsets.all(16),children:[_grid(context,[('Requests',m.requestCount.toString(),Icons.bolt),('Active',m.activeRequests.toString(),Icons.sync),('Completed',m.completedRequests.toString(),Icons.check_circle_outline),('Failed',m.failedRequests.toString(),Icons.error_outline),('Events',m.eventCount.toString(),Icons.timeline),('Tool calls',m.toolCallCount.toString(),Icons.build_circle_outlined)]),const SizedBox(height:18),_panel('Execution quality',[_line('Tool success rate','${(m.toolSuccessRate*100).toStringAsFixed(1)}%'),_line('Tool failures',m.toolFailureCount.toString()),_line('Interrupted requests',m.interruptedRequests.toString()),_line('Average tool latency',m.averageToolLatencyMs==null?'—':'${m.averageToolLatencyMs!.toStringAsFixed(0)} ms')]),const SizedBox(height:18),_panel('Lifecycle event distribution',m.eventTypes.entries.map((e)=>_line(e.key,e.value.toString())).toList())]);}}))));
 Widget _grid(BuildContext c,List<(String,String,IconData)> items)=>GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:MediaQuery.sizeOf(c).width>600?3:2,childAspectRatio:1.7,crossAxisSpacing:10,mainAxisSpacing:10,children:items.map((e)=>Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(gradient:ProTheme.cardGradient,borderRadius:BorderRadius.circular(15),border:Border.all(color:ProTheme.neonGreen.withOpacity(.15))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(e.$3,color:ProTheme.neonGreen),const Spacer(),Text(e.$2,style:const TextStyle(color:ProTheme.textPrimary,fontSize:22,fontWeight:FontWeight.bold)),Text(e.$1,style:const TextStyle(color:ProTheme.textSecondary,fontSize:12))]))).toList());
 Widget _panel(String title,List<Widget> children)=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(gradient:ProTheme.cardGradient,borderRadius:BorderRadius.circular(16)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:ProTheme.neonGreen,fontWeight:FontWeight.bold)),const Divider(color:Colors.white12),...children]));
 Widget _line(String k,String v)=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:Row(children:[Expanded(child:Text(k,style:const TextStyle(color:ProTheme.textSecondary))),Text(v,style:const TextStyle(color:ProTheme.textPrimary,fontWeight:FontWeight.w600))]));
}
